    {"step": 1, "tactic": "PowerShell creates self-signed CodeSigningCert with Microsoft-impersonating Subject", "technique": "T1553.002", "what_happened": "At 2026-05-17 13:18:10 UTC, AMSI EID 4104 captured 'New-SelfSignedCertificate -Type CodeSigningCert -Subject \"CN=Microsoft Security, O=Microsoft Corporation, L=Redmond, S=Washington, C=US\"' with KeyExportPolicy=Exportable. Rule 92001 triggered.", "chain_reason": "Subject 'Microsoft Security' on a self-signed cert + Type=CodeSigningCert = rogue cert designed to sign payload PE files. Microsoft never issues code-signing certs via user New-SelfSignedCertificate."},
    {"step": 2, "tactic": "Cert added to HKCU\\Software\\Microsoft\\SystemCertificates\\My (per-user cert store)", "technique": "T1553.002", "what_happened": "At 2026-05-17 13:18:13, Sysmon EID 13 captured registry SetValue on TargetObject='HKCU\\Software\\Microsoft\\SystemCertificates\\My\\Certificates\\<thumbprint>\\Blob' by powershell.exe.", "chain_reason": "Cert registered in user My store — necessary precondition for Set-AuthenticodeSignature."},
    {"step": 3, "tactic": "DECISIVE — Set-AuthenticodeSignature on PE in user Temp with the rogue cert", "technique": "T1553.002", "what_happened": "At 2026-05-17 13:18:18, AMSI 4104 captured 'Set-AuthenticodeSignature -FilePath C:\\Users\\k.anastasopoulou\\AppData\\Local\\Temp\\p120_cs_131810\\payload_signed_131810.exe -Certificate $cert'. At 13:18:19, Sysmon EID 11 captured the .exe file modified by powershell.exe (Authenticode signature appended). Rule 200305 triggered.", "chain_reason": "DECISIVE: signing arbitrary PE in user Temp with self-signed rogue cert = the smoking-gun T1553.002 success. The PE now carries a 'Microsoft Security' Authenticode signature that visually deceives users and bypasses some allow-listing tools."},
    {"step": 4, "tactic": "Export-PfxCertificate exfiltrates the rogue cert + private key", "technique": "T1553.002", "what_happened": "AMSI 4104 captured 'Export-PfxCertificate -Cert Cert:\\CurrentUser\\My\\<thumbprint> -FilePath C:\\Users\\k.anastasopoulou\\AppData\\Local\\Temp\\p120_cs_131810\\rogue_cs_131810.pfx -Password ...'. PFX file written to disk. Rule 92002 triggered.", "chain_reason": "PFX export = attacker preserving the private key for off-host signing infrastructure (signing more payloads later)."}
